import{_ as t,o,c as a,a2 as r}from"./chunks/framework.DKc58g3R.js";const h=JSON.parse('{"title":"API — Plotting","description":"Explore PyWorkforce coverage and staffing curves with optional Matplotlib plotting functions that return composable Axes objects.","frontmatter":{"description":"Explore PyWorkforce coverage and staffing curves with optional Matplotlib plotting functions that return composable Axes objects.","head":[["link",{"rel":"canonical","href":"https://pyworkforce.rodrigo-arenas.com/stable/api/plotting"}],["meta",{"property":"og:url","content":"https://pyworkforce.rodrigo-arenas.com/stable/api/plotting"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:title","content":"API — Plotting"}],["meta",{"property":"og:description","content":"Explore PyWorkforce coverage and staffing curves with optional Matplotlib plotting functions that return composable Axes objects."}],["meta",{"property":"og:image","content":"https://pyworkforce.rodrigo-arenas.com/stable/brand/social-preview.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"PyWorkforce shift coverage illustration"}]]},"headers":[],"relativePath":"api/plotting.md","filePath":"api/plotting.md","lastUpdated":1795113959000}'),n={name:"api/plotting.md"};function c(s,e,i,p,l,d){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="api-—-plotting" tabindex="-1">API — Plotting <a class="header-anchor" href="#api-—-plotting" aria-label="Permalink to &quot;API — Plotting&quot;">​</a></h1><p><code>pyworkforce.plotting</code> provides two functions for inspecting workforce results. Install <code>pyworkforce[plot]</code> to create charts. Each function returns the Matplotlib <code>Axes</code> it drew on. Pass <code>ax</code> to compose a figure, or omit it to create a new figure. Call <code>ax.figure.savefig(...)</code> or <code>matplotlib.pyplot.show()</code> when ready to export or display your result.</p><h2 id="plot-coverage-coverage-day-0-ax-none" tabindex="-1"><code>plot_coverage(coverage, *, day=0, ax=None)</code> <a class="header-anchor" href="#plot-coverage-coverage-day-0-ax-none" aria-label="Permalink to &quot;`plot_coverage(coverage, *, day=0, ax=None)`&quot;">​</a></h2><p>Pass the DataFrame returned by a shift scheduler&#39;s <code>coverage()</code> method. <code>day</code> selects a zero-based planning day. The horizontal axis marks the boundaries of each period, with scheduled and required headcounts drawn as steps. Shading marks intervals with a shortfall. A day absent from the frame raises <code>ValueError</code>.</p><p>See the <a href="/stable/guide/coverage-scenarios">schedule stress-test tutorial</a>.</p><h2 id="plot-staffing-curve-curve-ax-none" tabindex="-1"><code>plot_staffing_curve(curve, *, ax=None)</code> <a class="header-anchor" href="#plot-staffing-curve-curve-ax-none" aria-label="Permalink to &quot;`plot_staffing_curve(curve, *, ax=None)`&quot;">​</a></h2><p>Pass the DataFrame returned by <code>ErlangC.staffing_curve()</code>. The chart orders candidates by headcount and displays service level and occupancy as percentages. The headcount axis uses the counts supplied to <code>staffing_curve()</code>. It represents scheduled or productive positions according to that call&#39;s <code>scale_positions</code>.</p><p>See the <a href="/stable/guide/staffing-curve">staffing curve tutorial</a>.</p>',8)])])}const u=t(n,[["render",c]]);export{h as __pageData,u as default};
